final class Environment {
    private final Map<String, Double> variables;
    Environment(Map<String, Double> variables) {
        this.variables = Map.copyOf(variables); // obronna kopia + niemodyfikowalnosc
    }
    double get(String name) { return variables.get(name); }
}

Map<String, Double> bindings = new HashMap<>();
bindings.put("x", 3.0);
Environment env = new Environment(bindings);
bindings.put("x", 999.0); // mutacja PO utworzeniu
