static String opisz(Expr expr) {
    return switch (expr) {
        case Literal(double v) -> String.valueOf(v);
        case Variable(String n) -> n;
        case Add(Expr l, Expr r) -> "(" + opisz(l) + " + " + opisz(r) + ")";
        case Multiply(Expr l, Expr r) -> "(" + opisz(l) + " * " + opisz(r) + ")";
        case Negate(Expr e) -> "-(" + opisz(e) + ")";
        case Call(String name, Expr arg) -> name + "(" + opisz(arg) + ")";
    };
}
System.out.println(opisz(new Add(new Multiply(new Literal(2), new Variable("x")), new Call("sqrt", new Variable("y")))));

static int policzWezly(Expr expr) {
    return switch (expr) {
        case Literal l -> 1;
        case Variable v -> 1;
        case Add(Expr l, Expr r) -> 1 + policzWezly(l) + policzWezly(r);
        case Multiply(Expr l, Expr r) -> 1 + policzWezly(l) + policzWezly(r);
        case Negate(Expr e) -> 1 + policzWezly(e);
        case Call(String n, Expr a) -> 1 + policzWezly(a);
    };
}
Expr expression = new Add(new Multiply(new Literal(2), new Variable("x")), new Call("sqrt", new Variable("y")));
System.out.println(policzWezly(expression)); // 6

