static Expr uprosc(Expr expr) {
    return switch (expr) {
        case Multiply(Literal(double v), Expr r) when v == 0 -> new Literal(0);
        case Add(Literal(double v), Expr r) when v == 0 -> r;
        default -> expr;
    };
}
