class BinaryFunctionRegistry {
    private final Map<String, DoubleBinaryOperator> functions = new HashMap<>();
    void register(String name, DoubleBinaryOperator f) { functions.put(name, f); }
    Result<Double> apply(String name, double a, double b) {
        var f = functions.get(name);
        return f == null ? new Result.Failure<>("Nieznana funkcja: " + name) : new Result.Success<>(f.applyAsDouble(a, b));
