Map<Expr, Result<Double>> cache = new HashMap<>();
static Result<Double> evaluateCached(Expr expr, Environment env, FunctionRegistry fn, Map<Expr, Result<Double>> cache) {
    return cache.computeIfAbsent(expr, e -> evaluate(e, env, fn));
}

