static double evaluateOrThrow(Expr expr, Environment env, FunctionRegistry fn) {
    Result<Double> r = evaluate(expr, env, fn);
    return switch (r) {
        case Result.Success<Double> s -> s.value();
        case Result.Failure<Double> f -> throw new RuntimeException(f.message());
    };
}
// Result<T> lepszy: gdy blad jest OCZEKIWANYM, czestym wynikiem (np. brakujaca zmienna
// w interaktywnym edytorze wyrazen) - wymusza jawna obsluge OBU przypadkow przez kompilator,
// bez ryzyka 'zapomnianego catch'. Wyjatek lepszy: gdy blad jest FAKTYCZNIE wyjatkowy
// (np. blad programisty, ktory NIE powinien sie zdarzyc w normalnym uzyciu) i chcemy,
// zeby propagowal sie 'w gore' bez recznego przekazywania na kazdym poziomie wywolania -
// np. gdy wywolujemy evaluate() z glebokiego wnetrza wiekszego systemu, gdzie obsluga bledu
// jest scentralizowana wysoko w stosie wywolan.

