@Retention(RetentionPolicy.RUNTIME)
@Target(ElementType.METHOD)
@interface WymaganaZmienna { String value(); }

@WymaganaZmienna("x")
static Expr buildTestExpr() { return new Add(new Variable("x"), new Literal(1)); }

static Result<Double> evaluateWithCheck(java.lang.reflect.Method builder, Environment env, FunctionRegistry fn) throws Exception {
    WymaganaZmienna req = builder.getAnnotation(WymaganaZmienna.class);
    if (req != null && !env.has(req.value())) {
        return new Result.Failure<>("Brak wymaganej zmiennej: " + req.value());
    }
    Expr expr = (Expr) builder.invoke(null);
    return evaluate(expr, env, fn);
}

